import sminheapify = require( './index' );


// TESTS //

// The function returns a Float32Array...
{
	const x = new Float32Array( [ 7.0, 5.0, 3.0, 1.0, 9.0 ] );

	sminheapify( x.length, x, 1 ); // $ExpectType Float32Array
}

// The compiler throws an error if the function is provided a first argument which is not a number...
{
	const x = new Float32Array( 10 );

	sminheapify( '10', x, 1 ); // $ExpectError
	sminheapify( true, x, 1 ); // $ExpectError
	sminheapify( false, x, 1 ); // $ExpectError
	sminheapify( null, x, 1 ); // $ExpectError
	sminheapify( undefined, x, 1 ); // $ExpectError
	sminheapify( [], x, 1 ); // $ExpectError
	sminheapify( {}, x, 1 ); // $ExpectError
	sminheapify( ( x: number ): number => x, x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a second argument which is not a Float32Array...
{
	sminheapify( 5, 10, 1 ); // $ExpectError
	sminheapify( 5, '10', 1 ); // $ExpectError
	sminheapify( 5, true, 1 ); // $ExpectError
	sminheapify( 5, false, 1 ); // $ExpectError
	sminheapify( 5, null, 1 ); // $ExpectError
	sminheapify( 5, undefined, 1 ); // $ExpectError
	sminheapify( 5, [], 1 ); // $ExpectError
	sminheapify( 5, {}, 1 ); // $ExpectError
	sminheapify( 5, ( x: number ): number => x, 1 ); // $ExpectError
}

// The compiler throws an error if the function is provided a third argument which is not a number...
{
	const x = new Float32Array( 10 );

	sminheapify( x.length, x, '10' ); // $ExpectError
	sminheapify( x.length, x, true ); // $ExpectError
	sminheapify( x.length, x, false ); // $ExpectError
	sminheapify( x.length, x, null ); // $ExpectError
	sminheapify( x.length, x, undefined ); // $ExpectError
	sminheapify( x.length, x, [] ); // $ExpectError
	sminheapify( x.length, x, {} ); // $ExpectError
	sminheapify( x.length, x, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the function is provided an unsupported number of arguments...
{
	const x = new Float32Array( 10 );

	sminheapify(); // $ExpectError
	sminheapify( x.length ); // $ExpectError
	sminheapify( x.length, x ); // $ExpectError
	sminheapify( x.length, x, 1, {} ); // $ExpectError
}

// The ndarray function returns a Float32Array...
{
	const x = new Float32Array( [ 7.0, 5.0, 3.0, 1.0, 9.0 ] );

	sminheapify.ndarray( x.length, x, 1, 0 ); // $ExpectType Float32Array
}

// The compiler throws an error if the ndarray function is provided a first argument which is not a number...
{
	const x = new Float32Array( 10 );

	sminheapify.ndarray( '10', x, 1, 0 ); // $ExpectError
	sminheapify.ndarray( true, x, 1, 0 ); // $ExpectError
	sminheapify.ndarray( false, x, 1, 0 ); // $ExpectError
	sminheapify.ndarray( null, x, 1, 0 ); // $ExpectError
	sminheapify.ndarray( undefined, x, 1, 0 ); // $ExpectError
	sminheapify.ndarray( [], x, 1, 0 ); // $ExpectError
	sminheapify.ndarray( {}, x, 1, 0 ); // $ExpectError
	sminheapify.ndarray( ( x: number ): number => x, x, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the ndarray function is provided a second argument which is not a Float32Array...
{
	sminheapify.ndarray( 5, 10, 1, 0 ); // $ExpectError
	sminheapify.ndarray( 5, '10', 1, 0 ); // $ExpectError
	sminheapify.ndarray( 5, true, 1, 0 ); // $ExpectError
	sminheapify.ndarray( 5, false, 1, 0 ); // $ExpectError
	sminheapify.ndarray( 5, null, 1, 0 ); // $ExpectError
	sminheapify.ndarray( 5, undefined, 1, 0 ); // $ExpectError
	sminheapify.ndarray( 5, [], 1, 0 ); // $ExpectError
	sminheapify.ndarray( 5, {}, 1, 0 ); // $ExpectError
	sminheapify.ndarray( 5, ( x: number ): number => x, 1, 0 ); // $ExpectError
}

// The compiler throws an error if the ndarray function is provided a third argument which is not a number...
{
	const x = new Float32Array( 10 );

	sminheapify.ndarray( x.length, x, '10', 0 ); // $ExpectError
	sminheapify.ndarray( x.length, x, true, 0 ); // $ExpectError
	sminheapify.ndarray( x.length, x, false, 0 ); // $ExpectError
	sminheapify.ndarray( x.length, x, null, 0 ); // $ExpectError
	sminheapify.ndarray( x.length, x, undefined, 0 ); // $ExpectError
	sminheapify.ndarray( x.length, x, [], 0 ); // $ExpectError
	sminheapify.ndarray( x.length, x, {}, 0 ); // $ExpectError
	sminheapify.ndarray( x.length, x, ( x: number ): number => x, 0 ); // $ExpectError
}

// The compiler throws an error if the ndarray function is provided a fourth argument which is not a number...
{
	const x = new Float32Array( 10 );

	sminheapify.ndarray( x.length, x, 1, '10' ); // $ExpectError
	sminheapify.ndarray( x.length, x, 1, true ); // $ExpectError
	sminheapify.ndarray( x.length, x, 1, false ); // $ExpectError
	sminheapify.ndarray( x.length, x, 1, null ); // $ExpectError
	sminheapify.ndarray( x.length, x, 1, undefined ); // $ExpectError
	sminheapify.ndarray( x.length, x, 1, [] ); // $ExpectError
	sminheapify.ndarray( x.length, x, 1, {} ); // $ExpectError
	sminheapify.ndarray( x.length, x, 1, ( x: number ): number => x ); // $ExpectError
}

// The compiler throws an error if the ndarray function is provided an unsupported number of arguments...
{
	const x = new Float32Array( 10 );

	sminheapify.ndarray(); // $ExpectError
	sminheapify.ndarray( x.length ); // $ExpectError
	sminheapify.ndarray( x.length, x ); // $ExpectError
	sminheapify.ndarray( x.length, x, 1 ); // $ExpectError
	sminheapify.ndarray( x.length, x, 1, 0, {} ); // $ExpectError
}
